#include <map>
#include <vector>
#include <utility>

int main() {
    using PairType = std::pair<int, std::string>;

    std::vector<PairType> initial_data = {
        {1, "one"}, 
        {2, "two"}
    };

    // Range construction requires source elements to be pairs
    std::map<int, std::string> number_map(
        initial_data.begin(), 
        initial_data.end()
    );

    // number_map now contains (1, "one") and (2, "two")
}
